    }

    pub(crate) fn read_bytes(&self) -> Result<Vec<u8>, std::io::Error> {
        read_bytes_no_follow_path(&self.absolute_path)
    }

    pub(crate) fn sha256_hex(&self) -> Result<String, std::io::Error> {
